import{_ as e,c as n,o as a,a0 as o}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"nl/blog/pre-shot-routines.md","filePath":"nl/blog/pre-shot-routines.md"}');const i=e({name:"nl/blog/pre-shot-routines.md"},[["render",function(e,t,i,r,l,s){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="het-opbouwen-van-routines-voor-de-opname" tabindex="-1">Het opbouwen van routines vóór de opname <a class="header-anchor" href="#het-opbouwen-van-routines-voor-de-opname" aria-label="Permalink to &quot;Het opbouwen van routines vóór de opname&quot;">​</a></h1><p>Het verschil tussen een goede en een geweldige worp zit hem vaak al in het moment dat de boule je hand verlaat. Een goed doordachte voorbereiding is je anker in de hectiek van de wedstrijd – een betrouwbare reeks stappen die je lichaam en geest voorbereidt op optimale prestaties.</p><h2 id="waarom-routines-voor-de-opname-belangrijk-zijn" tabindex="-1">Waarom routines vóór de opname belangrijk zijn <a class="header-anchor" href="#waarom-routines-voor-de-opname-belangrijk-zijn" aria-label="Permalink to &quot;Waarom routines vóór de opname belangrijk zijn&quot;">​</a></h2><p>Topsporters in alle sporten gebruiken routines voorafgaand aan een worp. Bij pétanque, waar elke worp op zichzelf staat en de spanning tussen de worpen kan oplopen, dienen deze routines meerdere doelen:</p><ul><li><strong>Consistentie</strong>: Dezelfde voorbereiding leidt tot een consistentere uitvoering.</li><li><strong>Focus</strong>: Geef je geest een constructieve taak in plaats van je zorgen te maken.</li><li><strong>Overgang</strong>: Helpt je de overstap te maken van denken naar doen.</li><li><strong>Stressmanagement</strong>: Bekende handelingen kalmeren het zenuwstelsel.</li><li><strong>Reset</strong>: Hiermee wordt de vorige opname uit je geheugen gewist.</li></ul><h2 id="anatomie-van-een-effectieve-routine" tabindex="-1">Anatomie van een effectieve routine <a class="header-anchor" href="#anatomie-van-een-effectieve-routine" aria-label="Permalink to &quot;Anatomie van een effectieve routine&quot;">​</a></h2><p>Een goede voorbereiding op een fotosessie bestaat uit drie fasen:</p><h3 id="fase-1-beoordeling-5-10-seconden" tabindex="-1">Fase 1: Beoordeling (5-10 seconden) <a class="header-anchor" href="#fase-1-beoordeling-5-10-seconden" aria-label="Permalink to &quot;Fase 1: Beoordeling (5-10 seconden)&quot;">​</a></h3><ul><li>Lees het terrein</li><li>Visualiseer het beoogde resultaat.</li><li>Kies je werptype</li><li>Houd vast aan de beslissing.</li></ul><h3 id="fase-2-voorbereiding-5-10-seconden" tabindex="-1">Fase 2: Voorbereiding (5-10 seconden) <a class="header-anchor" href="#fase-2-voorbereiding-5-10-seconden" aria-label="Permalink to &quot;Fase 2: Voorbereiding (5-10 seconden)&quot;">​</a></h3><ul><li>Neem je positie in.</li><li>Vind je grip</li><li>Kom tot rust tijdens het ademhalen.</li><li>Voel het gewicht van de boule.</li></ul><h3 id="fase-3-uitvoering-3-5-seconden" tabindex="-1">Fase 3: Uitvoering (3-5 seconden) <a class="header-anchor" href="#fase-3-uitvoering-3-5-seconden" aria-label="Permalink to &quot;Fase 3: Uitvoering (3-5 seconden)&quot;">​</a></h3><ul><li>Laatste focus op het doel</li><li>Vertrouw op je lichaam.</li><li>Loslaten zonder na te denken</li><li>Ga er natuurlijk mee door</li></ul><h2 id="het-opbouwen-van-je-persoonlijke-routine" tabindex="-1">Het opbouwen van je persoonlijke routine <a class="header-anchor" href="#het-opbouwen-van-je-persoonlijke-routine" aria-label="Permalink to &quot;Het opbouwen van je persoonlijke routine&quot;">​</a></h2><h3 id="stap-1-observeer-je-huidige-patronen" tabindex="-1">Stap 1: Observeer je huidige patronen <a class="header-anchor" href="#stap-1-observeer-je-huidige-patronen" aria-label="Permalink to &quot;Stap 1: Observeer je huidige patronen&quot;">​</a></h3><p>Voordat je een nieuwe routine creëert, kijk eerst eens naar wat je al doet:</p><ul><li>Wat doe je voordat je een succesvolle worp maakt?</li><li>Wat verandert er als je onder druk staat?</li><li>Wat voelt voor jou natuurlijk aan?</li></ul><h3 id="stap-2-ontwerp-je-volgorde" tabindex="-1">Stap 2: Ontwerp je volgorde <a class="header-anchor" href="#stap-2-ontwerp-je-volgorde" aria-label="Permalink to &quot;Stap 2: Ontwerp je volgorde&quot;">​</a></h3><p>Stel een routine samen die het volgende omvat:</p><p><strong>Fysieke elementen:</strong></p><ul><li>Hoe je de cirkel benadert</li><li>Hoe je de boule oppakt en vasthoudt.</li><li>Uw houding en positionering</li><li>Een specifiek ademhalingspatroon</li></ul><p><strong>Mentale elementen:</strong></p><ul><li>Een visualisatie van het resultaat</li><li>Een kernwoord of -zin</li><li>Een beslissend moment (het moment waarop je besluit: &quot;dit is de worp&quot;).</li></ul><h3 id="stap-3-houd-het-simpel" tabindex="-1">Stap 3: Houd het simpel <a class="header-anchor" href="#stap-3-houd-het-simpel" aria-label="Permalink to &quot;Stap 3: Houd het simpel&quot;">​</a></h3><p>Je routine zou er als volgt uit moeten zien:</p><ul><li><strong>Kort genoeg</strong> om onder druk vol te houden (15-25 seconden in totaal)</li><li><strong>Simpel genoeg</strong> om te onthouden als je gestrest bent.</li><li><strong>Flexibel genoeg</strong> om zich aan verschillende situaties aan te passen.</li></ul><h2 id="voorbeelden-van-routines" tabindex="-1">Voorbeelden van routines <a class="header-anchor" href="#voorbeelden-van-routines" aria-label="Permalink to &quot;Voorbeelden van routines&quot;">​</a></h2><h3 id="de-routine-van-de-aanwijzer" tabindex="-1">De routine van de aanwijzer <a class="header-anchor" href="#de-routine-van-de-aanwijzer" aria-label="Permalink to &quot;De routine van de aanwijzer&quot;">​</a></h3><ol><li>Ga achter de cirkel staan en beoordeel het terrein.</li><li>Stel je het traject en de landingsplek van de boule voor.</li><li>Stap in de cirkel, vind je houding.</li><li>Drie langzame ademhalingen terwijl je de boule voelt.</li><li>Ogen op het doel, loslaten</li></ol><h3 id="de-routine-van-de-schutter" tabindex="-1">De routine van de schutter <a class="header-anchor" href="#de-routine-van-de-schutter" aria-label="Permalink to &quot;De routine van de schutter&quot;">​</a></h3><ol><li>Bepaal de doelboule en kies de hoek.</li><li>Visualiseer de impact en het resultaat.</li><li>Betreed de kring met een doel.</li><li>Haal diep adem en voel het gewicht.</li><li>Richt je blik op het doel en voer de actie uit.</li></ol><h2 id="veelgemaakte-fouten-die-je-moet-vermijden" tabindex="-1">Veelgemaakte fouten die je moet vermijden <a class="header-anchor" href="#veelgemaakte-fouten-die-je-moet-vermijden" aria-label="Permalink to &quot;Veelgemaakte fouten die je moet vermijden&quot;">​</a></h2><h3 id="te-lang" tabindex="-1">Te lang <a class="header-anchor" href="#te-lang" aria-label="Permalink to &quot;Te lang&quot;">​</a></h3><p>Als je routine langer dan 30 seconden duurt, denk je te veel na. Lange routines geven angst meer tijd om zich op te bouwen.</p><h3 id="te-stijf" tabindex="-1">Te stijf <a class="header-anchor" href="#te-stijf" aria-label="Permalink to &quot;Te stijf&quot;">​</a></h3><p>Als elke onderbreking je routine verstoort, is die te kwetsbaar. Zorg voor flexibiliteit: als iets je concentratie verstoort, zorg dan voor een manier om de draad weer op te pakken.</p><h3 id="touwtjespringen-onder-druk" tabindex="-1">Touwtjespringen onder druk <a class="header-anchor" href="#touwtjespringen-onder-druk" aria-label="Permalink to &quot;Touwtjespringen onder druk&quot;">​</a></h3><p>De routine is het belangrijkst wanneer de druk het hoogst is. Als je die routine loslaat wanneer je gestrest bent, verlies je de beschermende werking ervan.</p><h3 id="focus-op-mechanica" tabindex="-1">Focus op mechanica <a class="header-anchor" href="#focus-op-mechanica" aria-label="Permalink to &quot;Focus op mechanica&quot;">​</a></h3><p>Je routine moet eindigen met de focus op het resultaat, niet op de techniek. &quot;Raak het doel&quot; in plaats van &quot;houd je elleboog recht&quot;.</p><h2 id="je-routine-oefenen" tabindex="-1">Je routine oefenen <a class="header-anchor" href="#je-routine-oefenen" aria-label="Permalink to &quot;Je routine oefenen&quot;">​</a></h2><h3 id="in-opleiding" tabindex="-1">In opleiding <a class="header-anchor" href="#in-opleiding" aria-label="Permalink to &quot;In opleiding&quot;">​</a></h3><ul><li>Gebruik je volledige routine bij elke worp, zelfs bij de meest informele.</li><li>Neem de tijd om consistentie te garanderen.</li><li>Oefen met afleidingen om veerkracht op te bouwen.</li></ul><h3 id="automatisering-bouwen" tabindex="-1">Automatisering bouwen <a class="header-anchor" href="#automatisering-bouwen" aria-label="Permalink to &quot;Automatisering bouwen&quot;">​</a></h3><p>Het doel is dat je routine automatisch wordt – iets wat je doet zonder erbij na te denken. Dit vereist herhaling:</p><ul><li>Meer dan 100 worpen met dezelfde routine.</li><li>Consistent gebruik in verschillende situaties.</li><li>Geleidelijke blootstelling aan druk met behoud van de routine.</li></ul><h2 id="aanpassen-aan-de-concurrentie" tabindex="-1">Aanpassen aan de concurrentie <a class="header-anchor" href="#aanpassen-aan-de-concurrentie" aria-label="Permalink to &quot;Aanpassen aan de concurrentie&quot;">​</a></h2><p>Tijdens wedstrijden kan het nodig zijn je routine enigszins aan te passen:</p><ul><li><strong>Tijdsdruk</strong>: Zorg dat je een verkorte versie klaar hebt.</li><li><strong>Weersomstandigheden</strong>: Pas de fysieke elementen indien nodig aan.</li><li><strong>Momenten met hoge druk</strong>: Vertraag iets, maar versnel niet.</li></ul><h2 id="de-resetprocedure" tabindex="-1">De resetprocedure <a class="header-anchor" href="#de-resetprocedure" aria-label="Permalink to &quot;De resetprocedure&quot;">​</a></h2><p>Net zo belangrijk is wat je doet na een worp:</p><ol><li><strong>Accepteer het resultaat</strong> — goed of slecht, het is gebeurd.</li><li><strong>Fysieke reset</strong> — neem afstand en schud de spanning van je af.</li><li><strong>Mentale reset</strong> — maak de worp uit je gedachten.</li><li><strong>Bereid je voor op de toekomst</strong> — richt je aandacht op wat komen gaat.</li></ol><hr><p>| <em>Gerelateerd: <a href="/en/education/mental-strength/pre-shot-routine">Richtlijn voor de voorbereiding op de vaccinatie</a> | <a href="/en/education/mental-strength/handling-pressure">Omgaan met druk</a> | <a href="/en/education/mindfulness/techniques">Mindfulnesstechnieken</a></em> |</p>',54)])])}]]);export{t as __pageData,i as default};
